<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Adjustable Ground-Mounted Photovoltaic System</title>
  <style>
    :root {
      color-scheme: dark;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #cbd7df;
    }

    #scene {
      position: fixed;
      inset: 0;
    }

    .title-card {
      position: fixed;
      top: 24px;
      left: 24px;
      z-index: 5;
      max-width: min(390px, calc(100vw - 48px));
      padding: 17px 19px;
      color: #eef5f7;
      background: rgba(20, 31, 38, 0.82);
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 14px;
      box-shadow: 0 12px 35px rgba(20, 31, 38, 0.2);
      backdrop-filter: blur(12px);
      pointer-events: none;
    }

    .eyebrow {
      margin-bottom: 5px;
      color: #8fd2a4;
