      font-weight: 700;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(19px, 3vw, 26px);
      line-height: 1.15;
      letter-spacing: -0.025em;
    }

    .subtitle {
      margin: 8px 0 0;
      color: rgba(238, 245, 247, 0.67);
      font-size: 13px;
      line-height: 1.45;
    }

    .control-card {
      position: fixed;
      right: 24px;
      bottom: 24px;
      z-index: 6;
      width: 285px;
      padding: 17px;
      color: #edf3f5;
      background: rgba(20, 31, 38, 0.84);
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 14px;
      box-shadow: 0 12px 35px rgba(20, 31, 38, 0.22);
      backdrop-filter: blur(12px);
    }

    .control-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      margin-bottom: 10px;
    }

    .control-row label {
      font-size: 13px;
      font-weight: 650;
