      font-size: 11px;
      font-weight: 600;
      background: rgba(245, 249, 250, 0.72);
      border: 1px solid rgba(255, 255, 255, 0.55);
      border-radius: 9px;
      box-shadow: 0 5px 20px rgba(30, 45, 52, 0.1);
      backdrop-filter: blur(8px);
